#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

struct Trie {
    Trie* child[2] = {};
    int count = 0;
};

class Solution {
    Trie* root = new Trie;
    vector<vector<int>> tree;
    unordered_map<int, vector<pair<int, int>>> queryMap;
    vector<int> ans;

    void insert(int x) {
        Trie* node = root;
        for (int i = 17; i >= 0; --i) {
            int b = (x >> i) & 1;
            if (!node->child[b]) node->child[b] = new Trie;
            node = node->child[b];
            node->count++;
        }
    }

    void remove(int x) {
        Trie* node = root;
        for (int i = 17; i >= 0; --i) {
            int b = (x >> i) & 1;
            node = node->child[b];
            node->count--;
        }
    }

    int getMaxXor(int x) {
        Trie* node = root;
        int res = 0;
        for (int i = 17; i >= 0; --i) {
            int b = (x >> i) & 1;
            if (node->child[1 - b] && node->child[1 - b]->count > 0) {
                res |= (1 << i);
                node = node->child[1 - b];
            } else {
                node = node->child[b];
            }
        }
        return res;
    }

    void dfs(int u) {
        insert(u);
        for (auto& [x, idx] : queryMap[u]) {
            ans[idx] = getMaxXor(x);
        }
        for (int v : tree[u]) {
            dfs(v);
        }
        remove(u);
    }

public:
    vector<int> maxGeneticDifference(vector<int>& parents, vector<vector<int>>& queries) {
        int n = parents.size();
        tree.resize(n);
        int rootIdx = 0;
        for (int i = 0; i < n; ++i) {
            if (parents[i] == -1) rootIdx = i;
            else tree[parents[i]].push_back(i);
        }

        for (int i = 0; i < queries.size(); ++i) {
            queryMap[queries[i][0]].emplace_back(queries[i][1], i);
        }

        ans.resize(queries.size());
        dfs(rootIdx);
        return ans;
    }
};
